package mz.co.aprendaacodar.storage;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@Service public class SupabaseStorageService implements StorageService {
 private final String base,key,publicBucket,privateBucket;private final RestClient client;
 public SupabaseStorageService(@Value("${app.storage.supabase-url}") String base,@Value("${app.storage.service-role-key}") String key,@Value("${app.storage.public-bucket}") String publicBucket,@Value("${app.storage.private-bucket}") String privateBucket,RestClient.Builder builder){this.base=base;this.key=key;this.publicBucket=publicBucket;this.privateBucket=privateBucket;client=builder.build();}
 @Override public String upload(String folder,MultipartFile file,boolean isPublic){if(base.isBlank()||key.isBlank())throw new IllegalStateException("O armazenamento Supabase ainda não está configurado.");if(file.isEmpty()||file.getSize()>50L*1024*1024)throw new IllegalArgumentException("Ficheiro vazio ou superior a 50 MB.");String type=Optional.ofNullable(file.getContentType()).orElse("");Set<String> allowed=Set.of("image/jpeg","image/png","image/webp","application/pdf","application/msword","application/vnd.openxmlformats-officedocument.wordprocessingml.document");if(!allowed.contains(type))throw new IllegalArgumentException("Tipo de ficheiro não permitido.");String original=Objects.requireNonNullElse(file.getOriginalFilename(),"file");String extension=original.contains(".")?original.substring(original.lastIndexOf('.')+1).toLowerCase(Locale.ROOT):"";if(!Set.of("jpg","jpeg","png","webp","pdf","doc","docx").contains(extension))throw new IllegalArgumentException("Extensão de ficheiro não permitida.");boolean match=switch(type){case "image/jpeg"->Set.of("jpg","jpeg").contains(extension);case "image/png"->extension.equals("png");case "image/webp"->extension.equals("webp");case "application/pdf"->extension.equals("pdf");case "application/msword"->extension.equals("doc");default->extension.equals("docx");};if(!match)throw new IllegalArgumentException("A extensão não corresponde ao tipo MIME do ficheiro.");if((folder.startsWith("profiles/")||folder.startsWith("course-covers/")||folder.startsWith("blog-covers/"))&&!type.startsWith("image/"))throw new IllegalArgumentException("Esta operação aceita apenas imagens.");String objectKey=folder+"/"+UUID.randomUUID()+"."+extension;
  String bucket=isPublic?publicBucket:privateBucket;try{client.post().uri(base+"/storage/v1/object/"+bucket+"/"+objectKey).header("apikey",key).header(HttpHeaders.AUTHORIZATION,"Bearer "+key).header("x-upsert","false").contentType(MediaType.parseMediaType(type)).body(file.getBytes()).retrieve().toBodilessEntity();return objectKey;}catch(java.io.IOException e){throw new IllegalArgumentException("Não foi possível ler o ficheiro enviado.",e);}}
 @Override public String url(String objectKey,boolean isPublic){if(base.isBlank()||key.isBlank())throw new IllegalStateException("O armazenamento Supabase ainda não está configurado.");String bucket=isPublic?publicBucket:privateBucket;if(isPublic)return base+"/storage/v1/object/public/"+bucket+"/"+objectKey;Map<?,?> result=client.post().uri(base+"/storage/v1/object/sign/"+bucket+"/"+objectKey).header("apikey",key).header(HttpHeaders.AUTHORIZATION,"Bearer "+key).contentType(MediaType.APPLICATION_JSON).body(Map.of("expiresIn",300)).retrieve().body(Map.class);return base+Objects.toString(result==null?null:result.get("signedURL"),"");}
}
